  "verdict": "kill",
  "tests": [
    {
      "id": "R001",
      "result": "pass",
      "evidence": "Selling compute capacity to AI/cloud companies is not itself a regulated activity like filing on behalf of customers or handling licensed advice.",
      "source_url": null
    },
    {
      "id": "T2",
      "result": "pass",
      "evidence": "No dependency on a single revocable third-party platform API is inherent to the idea as written.",
      "source_url": null
    },
    {
      "id": "T3",
      "result": "unknown",
      "evidence": "Compute hardware/servers could theoretically be outsourced to a manufacturer, but the idea does not specify a fulfillment path; not the primary kill reason here.",
      "source_url": null
    },
    {
      "id": "T7",
      "result": "fail",
      "evidence": "Building and operating a fleet of standardized vessels as floating data centers requires shipyard construction, naval architecture, marine power/cooling systems, and large capital outlays. Real-world comparables confirm this: Panthalassa raised $140M (Series B) from Thiel/Doerr/Benioff for ocean data centers (https://fortune.com/2026/05/14/peter-thiel-leading-investment-ocean-data-center-panthalassa/); Hanwha Ocean, Samsung Heavy Industries, and Mitsui O.S.K. Lines (major shipbuilders/shipping conglomerates) are developing floating data center vessels, requiring shipyard-scale industrial capacity (https://www.thelec.net/news/articleView.html?idxno=13886, https://www.techspot.com/news/112738-samsung-building-floating-data-centers-ships-already-got.html). This is unambiguously beyond what one person with AI agents can capitalize or physically build/operate.",
      "source_url": "https://fortune.com/2026/05/14/peter-thiel-leading-investment-ocean-data-center-panthalassa/"
    }
  ],
  "flags": [
    { "id": "T4", "evidence": "Selling capacity to hyperscale AI/cloud companies would require enterprise procurement and long sales cycles typical of infrastructure deals." },
    { "id": "T6", "evidence": "Given multi-year shipyard build times (12-18 months minimum per Bluerax) and capital raises in the tens/hundreds of millions, no plausible path to a paying customer within 90 days." }
  ],
  "competitors": [
    { "name": "Panthalassa", "url": "https://fortune.com/2026/05/14/peter-thiel-leading-investment-ocean-data-center-panthalassa/", "relationship": "direct", "pricing": null, "evidence": "Raised $140M Series B (Thiel, Doerr, Benioff) to build wave-powered ocean data centers for AI compute." },
    { "name": "Optimal Transit (Kraaken)", "url": "https://optimaltransit.com/2026/07/03/optimal-transit-unveils-kraaken-the-worlds-first-self-powered-maritime-ai-infrastructure-platform-with-capex-opex-costs-at-a-fraction-of-conventional-land-based-facilities/", "relationship": "direct", "pricing": null, "evidence": "Standardized 10-100MW self-powered maritime AI data center platforms, joint venture of naval systems and power tech firms." },
    { "name": "Hanwha Ocean Floating Data Center", "url": "https://www.thelec.net/news/articleView.html?idxno=13886", "relationship": "direct", "pricing": null, "evidence": "Major shipbuilder unveiled 60MW modular floating data center with ABS Approval in Principle." },
    { "name": "Bluerax", "url": "https://bluerax.com/", "relationship": "direct", "pricing": null, "evidence": "Builds standardized floating datacenters in shipyards, 12-18 month deployment, for hyperscalers and governments." },
    { "name": "MOL/Hitachi/Kinetics Floating Data Center", "url": "https://www.mol.co.jp/en/pr/2026/26021.html", "relationship": "direct", "pricing": null, "evidence": "Major shipping company (Mitsui O.S.K. Lines) partnering with Hitachi and Samsung Heavy Industries on floating data center vessels." },
    { "name": "Seaforge", "url": "https://www.seaforgeusa.com/", "relationship": "direct", "pricing": null, "evidence": "Develops offshore data-center vessels with onboard power generation and liquid cooling, government-grade security standards." }
  ],
